#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    for (int t = 0; t < q; ++t) {
        long long x;
        scanf("%lld", &x);
        int pos = (int)(std::lower_bound(a.begin(), a.end(), x) - a.begin());
        printf("%d\n", pos < n ? pos + 1 : 0);
    }
    return 0;
}
